  CONSTRAINT `monitoring_report_details_monitoring_report_id_foreign` FOREIGN KEY (`monitoring_report_id`) REFERENCES `monitoring_reports` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=992 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `monitoring_reports`;
CREATE TABLE `monitoring_reports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `cooperative_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `cooperative_name` varchar(255) NOT NULL,
  `province` varchar(255) DEFAULT NULL,
  `municipality` varchar(255) DEFAULT NULL,
  `barangay` varchar(255) DEFAULT NULL,
  `report_date` date NOT NULL,
  `monitored_by` varchar(255) DEFAULT NULL,
  `attested_by` varchar(255) DEFAULT NULL,
  `noted_by` varchar(255) DEFAULT NULL,
  `report_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`report_data`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `monitoring_reports_cooperative_id_report_date_index` (`cooperative_id`,`report_date`),
  KEY `monitoring_reports_created_by_foreign` (`created_by`),
  CONSTRAINT `monitoring_reports_cooperative_id_foreign` FOREIGN KEY (`cooperative_id`) REFERENCES `cooperatives` (`id`) ON DELETE SET NULL,
  CONSTRAINT `monitoring_reports_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mtd_records`;
CREATE TABLE `mtd_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `carabao_id` bigint(20) unsigned DEFAULT NULL,
  `test_date` date NOT NULL,
  `milk_yield_liters` decimal(8,2) DEFAULT NULL,
  `fat_percentage` decimal(5,2) DEFAULT NULL,
  `snf_percentage` decimal(5,2) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `registry_number` varchar(255) DEFAULT NULL,
  `dryoff_date` date DEFAULT NULL,
  `test_day` tinyint(3) unsigned DEFAULT NULL,
  `days_in_milk` smallint(5) unsigned DEFAULT NULL,
  `mtd_value` decimal(8,2) DEFAULT NULL,
  `cooperative_id` bigint(20) unsigned DEFAULT NULL,
  `source_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`source_data`)),
  PRIMARY KEY (`id`),
  KEY `mtd_records_carabao_id_test_date_index` (`carabao_id`,`test_date`),
  KEY `mtd_records_registry_number_index` (`registry_number`),
  KEY `mtd_records_cooperative_id_foreign` (`cooperative_id`),
  CONSTRAINT `mtd_records_carabao_id_foreign` FOREIGN KEY (`carabao_id`) REFERENCES `carabaos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mtd_records_cooperative_id_foreign` FOREIGN KEY (`cooperative_id`) REFERENCES `cooperatives` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `nature_of_exits`;
CREATE TABLE `nature_of_exits` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `carabao_id` bigint(20) unsigned NOT NULL,
  `exit_date` date DEFAULT NULL,
  `nature_of_exit` varchar(255) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `cooperative_id` bigint(20) unsigned DEFAULT NULL,
  `registry_number` varchar(255) DEFAULT NULL,
  `farmer_name` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `nature_of_exits_carabao_id_foreign` (`carabao_id`),
  KEY `nature_of_exits_cooperative_id_foreign` (`cooperative_id`),
  KEY `nature_of_exits_registry_number_index` (`registry_number`),
  CONSTRAINT `nature_of_exits_carabao_id_foreign` FOREIGN KEY (`carabao_id`) REFERENCES `carabaos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `nature_of_exits_cooperative_id_foreign` FOREIGN KEY (`cooperative_id`) REFERENCES `cooperatives` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=373 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pending_cooperative_workbook_rows`;
CREATE TABLE `pending_cooperative_workbook_rows` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `identifier_id` bigint(20) unsigned NOT NULL,
  `batch_file_id` bigint(20) unsigned DEFAULT NULL,
  `workbook_import_id` bigint(20) unsigned DEFAULT NULL,
  `workbook_import_sheet_id` bigint(20) unsigned DEFAULT NULL,
  `target_table` varchar(100) NOT NULL,
  `source_row` int(10) unsigned NOT NULL,
  `source_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`source_data`)),
  `status` varchar(30) NOT NULL DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pending_coop_workbook_row_unique` (`workbook_import_sheet_id`,`source_row`),
  KEY `pending_coop_workbook_identifier_status_idx` (`identifier_id`,`status`),
  KEY `pending_coop_rows_batch_file_fk` (`batch_file_id`),
  KEY `pending_coop_rows_import_fk` (`workbook_import_id`),
  CONSTRAINT `pending_coop_rows_batch_file_fk` FOREIGN KEY (`batch_file_id`) REFERENCES `cooperative_workbook_batch_files` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pending_coop_rows_identifier_fk` FOREIGN KEY (`identifier_id`) REFERENCES `unmapped_cooperative_identifiers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pending_coop_rows_import_fk` FOREIGN KEY (`workbook_import_id`) REFERENCES `cooperative_workbook_imports` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pending_coop_rows_sheet_fk` FOREIGN KEY (`workbook_import_sheet_id`) REFERENCES `cooperative_workbook_import_sheets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=522 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `semen_bulls`;
CREATE TABLE `semen_bulls` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `bull_id` varchar(255) NOT NULL,
