  KEY `unmapped_coop_record_target_idx` (`record_table`,`record_id`),
  CONSTRAINT `unmapped_cooperative_records_identifier_id_foreign` FOREIGN KEY (`identifier_id`) REFERENCES `unmapped_cooperative_identifiers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `unmapped_cooperative_records_workbook_import_sheet_id_foreign` FOREIGN KEY (`workbook_import_sheet_id`) REFERENCES `cooperative_workbook_import_sheets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1467 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `role` varchar(255) NOT NULL DEFAULT 'admin',
